root = Path('BHS-EDoc-v3')
root.mkdir(exist_ok=True)
with ZipFile(BytesIO(decompress(b64decode(PAYLOAD)))) as archive:
    for file in archive.infolist():
        location = (root / file.filename).resolve()
        if not location.is_relative_to(root.resolve()):
            raise ValueError('Unexpected archive member path')
    archive.extractall(root)
print('Created', root.resolve())
print('Run: cd BHS-EDoc-v3 && npm install && npm run dev')
